// ============================================================
// CONFIGURATION — set your Kie AI API key in n8n Credentials
// or replace the env var below with your key directly.
// ============================================================
const KIE_API_KEY = $env['KIE_API_KEY'] ?? 'PASTE_YOUR_KIE_API_KEY_HERE';
const KIE_BASE = 'https://api.kie.ai/api/v1';
const POLL_INTERVAL_MS = 5000;   // how often to check task status
const MAX_POLL_ATTEMPTS = 144;   // 144 × 5s = 12 minutes max wait per task
const SUBMIT_DELAY_MS = 350;     // delay between task submissions (rate limit)

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// ── 1. Extract form data ───────────────────────────────────
const formItem = $input.first();
const email = formItem.json['Email Address'];

// ── 2. Parse CSV ───────────────────────────────────────────
const csvBin = formItem.binary?.['Prompts CSV'];
if (!csvBin) throw new Error('No CSV file found in upload.');

const csvText = Buffer.from(csvBin.data, 'base64').toString('utf-8');
const lines = csvText
  .replace(/\r\n/g, '\n')
  .replace(/\r/g, '\n')
  .split('\n')
  .map((l) => l.trim())
  .filter(Boolean);

// Auto-detect header row
const firstLower = (lines[0] ?? '').toLowerCase();
const hasHeader =
  firstLower.includes('prompt') ||
  firstLower.includes('text') ||
  firstLower.includes('description') ||
  firstLower.includes('scene') ||
  firstLower.includes('caption');
const startIdx = hasHeader ? 1 : 0;

const prompts = [];
for (let i = startIdx; i < lines.length; i++) {
  // Strip surrounding quotes and unescape doubled quotes
  const raw = lines[i].split(',')[0]; // take first CSV column
  const prompt = raw.replace(/^"|"$/g, '').replace(/""/g, '"').trim();
  if (prompt) prompts.push(prompt);
}

if (prompts.length === 0)
  throw new Error('No prompts found in CSV. Make sure prompts are in the first column.');

// ── 3. Upload reference image to Kie AI ───────────────────
const refBin = formItem.binary?.['Character Reference Image'];
if (!refBin) throw new Error('No character reference image found in upload.');

const refBuffer = Buffer.from(refBin.data, 'base64');
const refMime = refBin.mimeType ?? 'image/jpeg';
const refName = refBin.fileName ?? 'character_reference.jpg';

const uploadForm = new FormData();
uploadForm.append('file', new Blob([refBuffer], { type: refMime }), refName);

const uploadRes = await fetch(`${KIE_BASE}/upload`, {
  method: 'POST',
  headers: { Authorization: `Bearer ${KIE_API_KEY}` },
  body: uploadForm,
});

if (!uploadRes.ok) {
  const errBody = await uploadRes.text();
  throw new Error(`Reference image upload failed (${uploadRes.status}): ${errBody}`);
}

const uploadJson = await uploadRes.json();
const refImageUrl = uploadJson?.data?.url ?? uploadJson?.url;
if (!refImageUrl)
  throw new Error(`Upload response missing URL: ${JSON.stringify(uploadJson)}`);

// ── 4. Submit all generation tasks ────────────────────────
const tasks = []; // { index, prompt, taskId | null, error }

for (let i = 0; i < prompts.length; i++) {
  if (i > 0) await sleep(SUBMIT_DELAY_MS);

  const createRes = await fetch(`${KIE_BASE}/jobs/createTask`, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${KIE_API_KEY}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      model: 'nano-banana-2',
      input: {
        prompt: prompts[i],
        image_input: [refImageUrl],
        aspect_ratio: 'auto',
        resolution: '1K',
        output_format: 'png',
      },
    }),
  });

  if (!createRes.ok) {
    const err = await createRes.text();
    console.error(`[${i + 1}/${prompts.length}] Task create failed: ${err}`);
    tasks.push({ index: i, prompt: prompts[i], taskId: null, error: err });
    continue;
  }

  const createJson = await createRes.json();
  const taskId = createJson?.data?.taskId ?? createJson?.taskId;
  tasks.push({ index: i, prompt: prompts[i], taskId });
}

// ── 5. Poll all tasks until every one completes ───────────
const imageUrls = new Array(prompts.length).fill(null);
const pollCount = {};
const pending = new Set(
  tasks.filter((t) => t.taskId).map((t) => t.index)
);
for (const idx of pending) pollCount[idx] = 0;

while (pending.size > 0) {
  await sleep(POLL_INTERVAL_MS);

  const done = [];
  for (const i of pending) {
    pollCount[i]++;
    if (pollCount[i] > MAX_POLL_ATTEMPTS) {
      console.error(`Task ${i + 1} timed out.`);
      done.push(i);
      continue;
    }

    const { taskId } = tasks[i];
    try {
      const pollRes = await fetch(
        `${KIE_BASE}/jobs/getTaskDetail?taskId=${taskId}`,
        { headers: { Authorization: `Bearer ${KIE_API_KEY}` } }
      );
      if (!pollRes.ok) continue;

      const pollJson = await pollRes.json();
      const status = (pollJson?.data?.status ?? '').toUpperCase();

      if (status === 'SUCCESS' || status === 'COMPLETED') {
        const output = pollJson?.data?.output;
        imageUrls[i] = Array.isArray(output) ? output[0] : output;
        done.push(i);
      } else if (status === 'FAILED' || status === 'ERROR') {
        console.error(`Task ${i + 1} failed on server.`);
        done.push(i);
      }
    } catch (e) {
      console.error(`Poll error for task ${i + 1}: ${e.message}`);
    }
  }

  for (const i of done) pending.delete(i);
}

// ── 6. Download all generated images ──────────────────────
const resultItems = [];

for (let i = 0; i < imageUrls.length; i++) {
  const url = imageUrls[i];
  if (!url) continue;

  try {
    const imgRes = await fetch(url);
    if (!imgRes.ok) {
      console.error(`Download failed for image ${i + 1}: ${imgRes.status}`);
      continue;
    }

    const imgBuffer = Buffer.from(await imgRes.arrayBuffer());
    const pad = String(i + 1).padStart(3, '0');

    resultItems.push({
      json: {
        email,
        prompt: prompts[i],
        index: i + 1,
        totalGenerated: imageUrls.filter(Boolean).length,
        totalRequested: prompts.length,
        imageUrl: url,
      },
      binary: {
        image: {
          data: imgBuffer.toString('base64'),
          mimeType: 'image/png',
          fileName: `image_${pad}.png`,
          fileExtension: 'png',
        },
      },
    });
  } catch (e) {
    console.error(`Error downloading image ${i + 1}: ${e.message}`);
  }
}

if (resultItems.length === 0)
  throw new Error(
    'No images were generated successfully. Check your API key, prompts, and Kie AI credits.'
  );

return resultItems;
